package org.springframework.samples.petclinic.rest.function.common;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives the owner's {@code membershipPoints} and the numeric {@code membershipLevel} mapped from
 * them.
 *
 * <p>Points start at 0 and accumulate: 2 when the owner has an email address on record, 1 when the
 * owner had no namesakes at creation ({@code namesakeCount} is 0), 2 for a household of 3 or more
 * members, and 3 when the owner's tenure exceeds one elapsed fiscal year. The points then map to a
 * level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly created owner
 * has zero tenure, the +3 tenure award is out of reach at creation, so a new owner scores at most 5
 * points (2 email + 1 namesake + 2 household) and never exceeds level 3.
 */
public final class Membership {

    /** Household size, in members, at or above which the household points are granted. */
    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;

    /** Tenure, in elapsed fiscal years, that must be exceeded before the tenure points are granted. */
    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;

    private Membership() {
    }

    /** The owner's membership points, from 0 upwards. */
    public static int pointsOf(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += 1;
        }
        if (owner.getHouseholdMemberCount() != null
                && owner.getHouseholdMemberCount() >= HOUSEHOLD_SIZE_FOR_POINTS) {
            points += 2;
        }
        if (FiscalYears.elapsedSinceRegistration(owner) > TENURE_FISCAL_YEARS_FOR_POINTS) {
            points += 3;
        }
        return points;
    }

    /** The owner's numeric membership level, mapped from {@link #pointsOf(Owner)}: 1 for 0-1
     * points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
    public static int levelOf(Owner owner) {
        int points = pointsOf(owner);
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }

    /** Days elapsed since the owner's registration date; 0 when no date is on record. */
    private static long tenureDays(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return 0;
        }
        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.rest.function.common.AgeBands;
import org.springframework.samples.petclinic.rest.function.common.CheckDigits;
import org.springframework.samples.petclinic.rest.function.common.ContactPreferences;
import org.springframework.samples.petclinic.rest.function.common.CustomerCodes;
import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;
import org.springframework.samples.petclinic.rest.function.common.Membership;
import org.springframework.samples.petclinic.rest.function.common.Telephones;
import org.springframework.samples.petclinic.rest.function.common.Timezones;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class,
        imports = { AgeBands.class, CheckDigits.class, ContactPreferences.class, CustomerCodes.class,
                IdentityKeys.class, Membership.class, Telephones.class, Timezones.class })
public interface OwnerMapper {

    @Mapping(target = "displayName",
            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "salutation",
            expression = "java(owner.getTitle() == null || owner.getTitle().isBlank() "
                    + "? owner.getLastName() : owner.getTitle() + \" \" + owner.getLastName())")
    @Mapping(target = "initials",
            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
                    + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "checkDigit",
            expression = "java(CheckDigits.luhnOf(owner.getCustomerCode()))")
    @Mapping(target = "membershipPoints",
            expression = "java(Membership.pointsOf(owner))")
    @Mapping(target = "membershipLevel",
            expression = "java(Membership.levelOf(owner))")
    @Mapping(target = "locality",
            expression = "java(CustomerCodes.localityOf(owner))")
    @Mapping(target = "timezone",
            expression = "java(Timezones.ofOwner(owner))")
    @Mapping(target = "contactPreference",
            expression = "java(ContactPreferences.of(owner))")
    @Mapping(target = "identityKey",
            expression = "java(IdentityKeys.of(owner))")
    @Mapping(target = "ageBand",
            expression = "java(AgeBands.of(owner))")
    @Mapping(target = "telephoneDisplay",
            expression = "java(Telephones.displayOf(owner))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

